-- Read-only supporting catalog export for offline W10 rehearsal. No passwords or rows.
select jsonb_build_object(
 'roles',(select jsonb_agg(jsonb_build_object('name',rolname,'inherit',rolinherit,'bypassrls',rolbypassrls,'canlogin',rolcanlogin)) from pg_roles where rolname not like 'pg_%'),
 'memberships',(select jsonb_agg(jsonb_build_object('role',r.rolname,'member',m.rolname,'admin',am.admin_option)) from pg_auth_members am join pg_roles r on r.oid=am.roleid join pg_roles m on m.oid=am.member where r.rolname not like 'pg_%' and m.rolname not like 'pg_%'),
 'schema_acls',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'owner',pg_get_userbyid(n.nspowner),'grantee',case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,'privilege',x.privilege_type,'grantable',x.is_grantable)) from pg_namespace n cross join lateral aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x where n.nspname in ('public','auth','storage','crm_private','extensions')),
 'default_acls',(select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'kind',d.defaclobjtype,'grantee',case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,'privilege',x.privilege_type,'grantable',x.is_grantable)) from pg_default_acl d join pg_namespace n on n.oid=d.defaclnamespace cross join lateral aclexplode(d.defaclacl) x where n.nspname in ('public','auth','storage')),
 'sequence_ownership',(select jsonb_agg(jsonb_build_object('sequence_schema',sn.nspname,'sequence',s.relname,'table_schema',tn.nspname,'table',t.relname,'column',a.attname,'kind',d.deptype)) from pg_depend d join pg_class s on s.oid=d.objid join pg_namespace sn on sn.oid=s.relnamespace join pg_class t on t.oid=d.refobjid join pg_namespace tn on tn.oid=t.relnamespace join pg_attribute a on a.attrelid=t.oid and a.attnum=d.refobjsubid where d.classid='pg_class'::regclass and d.refclassid='pg_class'::regclass and s.relkind='S' and sn.nspname in ('public','auth','storage') and d.deptype in ('a','i')),
 'unhandled_types',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'kind',t.typtype)) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','auth','storage','crm_private') and t.typtype not in ('e','b') and not exists(select 1 from pg_class c where c.reltype=t.oid)),
 'table_kinds',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'kind',c.relkind,'count',cnt)) from (select relnamespace,relkind,count(*) cnt from pg_class where relkind in ('p','f','m') group by relnamespace,relkind)c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','auth','storage','crm_private')),
 'database',(select jsonb_build_object('owner',pg_get_userbyid(datdba),'collate',datcollate,'ctype',datctype) from pg_database where datname=current_database())
) as metadata;

